class BIT:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)
    def add(self, i, v):
        i += 1
        while i <= self.n:
            self.t[i] += v
            i += i & (-i)
    def qry(self, i):
        i += 1
        s = 0
        while i > 0:
            s += self.t[i]
            i -= i & (-i)
        return s
    def rng(self, l, r):
        return self.qry(r) - self.qry(l - 1)

class Solution:
    def minDeletions(self, s: str, queries: List[List[int]]) -> List[int]:
        n = len(s)
        be, bo = BIT(n), BIT(n)
        for i, ch in enumerate(s):
            if ch == 'A':
                (be if i % 2 == 0 else bo).add(i, 1)
        res = []
        for q in queries:
            if q[0] == 1:
                j = q[1]
                t = be if j % 2 == 0 else bo
                if s[j] == 'A':
                    t.add(j, -1); s[j] = 'B'
                else:
                    t.add(j, 1); s[j] = 'A'
            else:
                l, r = q[1], q[2]
                E = (r - l)//2 + 1 if l % 2 == 0 else (r - l + 1)//2
                O = (r - l + 1) - E
                aE, aO = be.rng(l, r), bo.rng(l, r)
                res.append(min((E - aE) + aO, aE + (O - aO)))
        return res

