var minDeletions = function(sIn, queries) {
    const s = sIn.split(''), n = s.length;
    const mk = () => new Array(n + 1).fill(0);
    const te = mk(), to = mk();
    const add = (t, i, v) => { for (i++; i <= n; i += i & (-i)) t[i] += v; };
    const qry = (t, i) => { let s2 = 0; for (i++; i > 0; i -= i & (-i)) s2 += t[i]; return s2; };
    const rng = (t, l, r) => qry(t, r) - qry(t, l - 1);
    for (let i = 0; i < n; i++)
        if (s[i] === 'A') add(i % 2 === 0 ? te : to, i, 1);
    const res = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const j = q[1], t = j % 2 === 0 ? te : to;
            if (s[j] === 'A') { add(t, j, -1); s[j] = 'B'; }
            else { add(t, j, 1); s[j] = 'A'; }
        } else {
            const [l, r] = [q[1], q[2]];
            const E = l % 2 === 0 ? Math.floor((r - l) / 2) + 1 : Math.floor((r - l + 1) / 2);
            const O = (r - l + 1) - E;
            const aE = rng(te, l, r), aO = rng(to, l, r);
            res.push(Math.min((E - aE) + aO, aE + (O - aO)));
        }
    }
    return res;
};

