class Solution {
public:
    vector<int> minDeletions(string s, vector<vector<int>>& queries) {
        int n = s.size(), size = 1;
        while (size < n) size *= 2;
        vector<array<int,2>> tr(2 * size, {0,0});
        for (int i = 0; i < n; i++) {
            char ch = s[i];
            tr[size+i] = {(i%2==0 ? ch!='A' : ch!='B'), (i%2==0 ? ch!='B' : ch!='A')};
        }
        for (int i = size - 1; i >= 1; i--)
            tr[i] = {tr[2*i][0]+tr[2*i+1][0], tr[2*i][1]+tr[2*i+1][1]};
        vector<int> res;
        for (auto& q : queries) {
            if (q[0] == 1) {
                int j = q[1];
                s[j] = (s[j]=='A') ? 'B' : 'A';
                char ch = s[j];
                tr[size+j] = {(j%2==0 ? ch!='A' : ch!='B'), (j%2==0 ? ch!='B' : ch!='A')};
                for (int i = (size+j)/2; i >= 1; i /= 2)
                    tr[i] = {tr[2*i][0]+tr[2*i+1][0], tr[2*i][1]+tr[2*i+1][1]};
            } else {
                int l = q[1]+size, r = q[2]+size, m0 = 0, m1 = 0;
                while (l <= r) {
                    if (l & 1) { m0 += tr[l][0]; m1 += tr[l][1]; l++; }
                    if (!(r & 1)) { m0 += tr[r][0]; m1 += tr[r][1]; r--; }
                    l /= 2; r /= 2;
                }
                res.push_back(min(m0, m1));
            }
        }
        return res;
    }
};

