class Solution {
    public int[] minDeletions(String sIn, int[][] queries) {
        char[] s = sIn.toCharArray();
        int n = s.length, size = 1;
        while (size < n) size *= 2;
        int[][] tr = new int[2 * size][2];
        for (int i = 0; i < n; i++) {
            char ch = s[i];
            tr[size+i][0] = (i % 2 == 0 ? ch != 'A' : ch != 'B') ? 1 : 0;
            tr[size+i][1] = (i % 2 == 0 ? ch != 'B' : ch != 'A') ? 1 : 0;
        }
        for (int i = size - 1; i >= 1; i--) {
            tr[i][0] = tr[2*i][0] + tr[2*i+1][0];
            tr[i][1] = tr[2*i][1] + tr[2*i+1][1];
        }
        int[] res = new int[queries.length];
        for (int qi = 0; qi < queries.length; qi++) {
            int[] q = queries[qi];
            if (q[0] == 1) {
                int j = q[1];
                s[j] = (s[j] == 'A') ? 'B' : 'A';
                char ch = s[j];
                tr[size+j][0] = (j % 2 == 0 ? ch != 'A' : ch != 'B') ? 1 : 0;
                tr[size+j][1] = (j % 2 == 0 ? ch != 'B' : ch != 'A') ? 1 : 0;
                for (int i = (size + j) / 2; i >= 1; i /= 2) {
                    tr[i][0] = tr[2*i][0] + tr[2*i+1][0];
                    tr[i][1] = tr[2*i][1] + tr[2*i+1][1];
                }
            } else {
                int l = q[1] + size, r = q[2] + size, m0 = 0, m1 = 0;
                while (l <= r) {
                    if ((l & 1) == 1) { m0 += tr[l][0]; m1 += tr[l][1]; l++; }
                    if ((r & 1) == 0) { m0 += tr[r][0]; m1 += tr[r][1]; r--; }
                    l /= 2; r /= 2;
                }
                res[qi] = Math.min(m0, m1);
            }
        }
        return res;
    }
}

