var minDeletions = function(sIn, queries) {
    const s = sIn.split(''), n = s.length;
    let size = 1;
    while (size < n) size *= 2;
    const tr = Array.from({length: 2 * size}, () => [0, 0]);
    const leaf = (i, ch) => [i % 2 === 0 ? ch !== 'A' : ch !== 'B', i % 2 === 0 ? ch !== 'B' : ch !== 'A'].map(Number);
    for (let i = 0; i < n; i++) tr[size + i] = leaf(i, s[i]);
    for (let i = size - 1; i >= 1; i--) {
        tr[i][0] = tr[2*i][0] + tr[2*i+1][0];
        tr[i][1] = tr[2*i][1] + tr[2*i+1][1];
    }
    const res = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const j = q[1];
            s[j] = s[j] === 'A' ? 'B' : 'A';
            tr[size + j] = leaf(j, s[j]);
            for (let i = (size + j) >> 1; i >= 1; i >>= 1) {
                tr[i][0] = tr[2*i][0] + tr[2*i+1][0];
                tr[i][1] = tr[2*i][1] + tr[2*i+1][1];
            }
        } else {
            let l = q[1] + size, r = q[2] + size, m0 = 0, m1 = 0;
            while (l <= r) {
                if (l & 1) { m0 += tr[l][0]; m1 += tr[l][1]; l++; }
                if (!(r & 1)) { m0 += tr[r][0]; m1 += tr[r][1]; r--; }
                l >>= 1; r >>= 1;
            }
            res.push(Math.min(m0, m1));
        }
    }
    return res;
};
